    <tr><th>Decade</th><th>Mean Rate (per 100k)</th><th>Median Rate (per 100k)</th><th>Change vs. Prior Decade</th></tr>
    <tr><td>1990s</td><td>{d90:.2f}</td><td>{decade_medians.get(1990, 0):.2f}</td><td>—</td></tr>
    <tr><td>2000s</td><td>{d00:.2f}</td><td>{decade_medians.get(2000, 0):.2f}</td><td>{chg_90_00:+.1f}% (mean)</td></tr>
    <tr><td>2010s</td><td>{d10:.2f}</td><td>{decade_medians.get(2010, 0):.2f}</td><td>{chg_00_10:+.1f}% (mean)</td></tr>
    <tr><td>2020s</td><td>{d20:.2f}</td><td>{decade_medians.get(2020, 0):.2f}</td><td>{chg_10_20:+.1f}% (mean)</td></tr>
