  </div>

  <h3>Top 10 Highest Homicide Rates ({most_recent_year})</h3>
  <table>
    <tr><th>Country</th><th>ISO Code</th><th>Homicide Rate (per 100k)</th><th>Year</th></tr>
    {build_top10_table()}
  </table>

  <h3>Bottom 10 Lowest Homicide Rates ({most_recent_year})</h3>
