#!/usr/bin/env python3
"""
Generate the Global Intentional Homicide Trends Report (1990-2023).
Produces a self-contained HTML report with embedded charts and data tables.
"""

import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import numpy as np
import base64
from io import BytesIO
import warnings
warnings.filterwarnings('ignore')

# ─── Configuration ───────────────────────────────────────────────────────────
DATA_PATH = '/app/benchmark/data.csv'
OUTPUT_PATH = '/app/output/final_report.html'

# Color palette - professional, accessible
COLORS = {
    'primary': '#1a365d',
    'secondary': '#2b6cb0',
    'accent': '#e53e3e',
    'success': '#38a169',
    'warning': '#d69e2e',
    'bg_light': '#f7fafc',
    'bg_card': '#ffffff',
    'text': '#1a202c',
    'text_muted': '#718096',
    'border': '#e2e8f0',
    'chart_line': '#2b6cb0',
    'chart_line2': '#e53e3e',
    'chart_line3': '#38a169',
    'male': '#2b6cb0',
    'female': '#d53f8c',
    'age_colors': ['#2b6cb0', '#38a169', '#d69e2e', '#e53e3e', '#805ad5', '#dd6b20'],
}

plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.titlesize': 13,
    'axes.labelsize': 11,
    'figure.facecolor': 'white',
    'axes.facecolor': '#f8fafc',
    'axes.grid': True,
    'grid.alpha': 0.3,
    'grid.color': '#cbd5e0',
})


# ─── Data Loading ────────────────────────────────────────────────────────────
df = pd.read_csv(DATA_PATH)
df.columns = df.columns.str.strip()

# Key subsets
both_all = df[(df['sex'] == 'both') & (df['age_group'] == 'ALL')].copy()
male_all = df[(df['sex'] == 'male') & (df['age_group'] == 'ALL')].copy()
female_all = df[(df['sex'] == 'female') & (df['age_group'] == 'ALL')].copy()

# Age-group data (sex=both, age_group != ALL)
age_data = df[(df['sex'] == 'both') & (df['age_group'] != 'ALL')].copy()

# ─── Helper: chart to base64 ─────────────────────────────────────────────────
def chart_to_base64(fig, dpi=130):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return b64


# ─── KPI Computations ────────────────────────────────────────────────────────
# 1) Global Median Homicide Rate (most recent year per country)
latest_per_country = both_all.sort_values('year').groupby('country').last()
most_recent_year = int(both_all['year'].max())
most_recent_data = both_all[both_all['year'] == most_recent_year]
global_median_latest = most_recent_data['homicide_rate'].median()
global_mean_latest = most_recent_data['homicide_rate'].mean()
n_countries_latest = most_recent_data['country'].nunique()

# 2) Male-to-Female Ratio (global, using countries that report both)
sex_merged = pd.merge(
    male_all[['country', 'year', 'homicide_rate']].rename(columns={'homicide_rate': 'male_rate'}),
    female_all[['country', 'year', 'homicide_rate']].rename(columns={'homicide_rate': 'female_rate'}),
    on=['country', 'year'],
    how='inner'
)
sex_merged['mf_ratio'] = sex_merged['male_rate'] / sex_merged['female_rate'].replace(0, np.nan)
mf_ratio_global = sex_merged.groupby('year')['mf_ratio'].median()
latest_mf_ratio = mf_ratio_global.iloc[-1] if len(mf_ratio_global) > 0 else None

# 3) Highest National Homicide Rate
highest_idx = most_recent_data['homicide_rate'].idxmax()
highest_country = most_recent_data.loc[highest_idx, 'country']
highest_rate = most_recent_data.loc[highest_idx, 'homicide_rate']
highest_year = int(most_recent_data.loc[highest_idx, 'year'])

# 4) Decade-over-Decade Change
both_all['decade'] = (both_all['year'] // 10) * 10
decade_means = both_all.groupby('decade')['homicide_rate'].mean()
decade_medians = both_all.groupby('decade')['homicide_rate'].median()

# 5) Reporting Coverage Rate
total_countries = df['country'].nunique()
coverage_by_year = both_all.groupby('year')['country'].nunique()
coverage_rate_by_year = coverage_by_year / total_countries * 100

# ─── Chart 1: Global Trend (Median & Mean over time) ────────────────────────
global_trend = both_all.groupby('year')['homicide_rate'].agg(['median', 'mean', 'count']).reset_index()

fig, ax1 = plt.subplots(figsize=(10, 5))
ax1.plot(global_trend['year'], global_trend['median'], color=COLORS['chart_line'],
         linewidth=2.5, marker='o', markersize=4, label='Median Rate', zorder=3)
ax1.plot(global_trend['year'], global_trend['mean'], color=COLORS['chart_line2'],
         linewidth=2, linestyle='--', marker='s', markersize=3, label='Mean Rate', zorder=3)
ax1.set_xlabel('Year')
ax1.set_ylabel('Homicide Rate (per 100,000)')
ax1.set_title('Global Homicide Rate Trend (1990–2023)')
ax1.legend(loc='upper right')
ax1.set_xlim(1989, 2024)

ax2 = ax1.twinx()
ax2.bar(global_trend['year'], global_trend['count'], alpha=0.15, color=COLORS['secondary'],
        label='Countries Reporting', width=0.8)
ax2.set_ylabel('Number of Countries Reporting')
ax2.set_ylim(0, global_trend['count'].max() * 1.3)
ax2.legend(loc='upper left')

fig.tight_layout()
chart1_b64 = chart_to_base64(fig)


# ─── Chart 2: Top 10 & Bottom 10 Countries (most recent year) ───────────────
sorted_latest = most_recent_data.sort_values('homicide_rate', ascending=False)
top10 = sorted_latest.head(10)
bottom10 = sorted_latest.tail(10).sort_values('homicide_rate', ascending=True)

fig, (ax_t, ax_b) = plt.subplots(1, 2, figsize=(12, 5))

# Top 10
colors_top = [COLORS['accent'] if r > 30 else '#e53e3e' if r > 15 else COLORS['warning']
              for r in top10['homicide_rate']]
ax_t.barh(top10['country'], top10['homicide_rate'], color=colors_top, edgecolor='white')
ax_t.set_xlabel('Homicide Rate (per 100,000)')
ax_t.set_title(f'Top 10 Highest Rates ({most_recent_year})')
ax_t.invert_yaxis()
for i, (v, c) in enumerate(zip(top10['homicide_rate'], top10['country'])):
    ax_t.text(v + 0.3, i, f'{v:.1f}', va='center', fontsize=9, fontweight='bold')

# Bottom 10
ax_b.barh(bottom10['country'], bottom10['homicide_rate'], color=COLORS['success'],
          edgecolor='white')
ax_b.set_xlabel('Homicide Rate (per 100,000)')
ax_b.set_title(f'Bottom 10 Lowest Rates ({most_recent_year})')
ax_b.invert_yaxis()
for i, v in enumerate(bottom10['homicide_rate']):
    ax_b.text(v + 0.05, i, f'{v:.2f}', va='center', fontsize=9, fontweight='bold')

fig.tight_layout()
chart2_b64 = chart_to_base64(fig)


# ─── Chart 3: Gender Disparity Over Time ─────────────────────────────────────
fig, (ax_l, ax_r) = plt.subplots(1, 2, figsize=(12, 5))

# Male vs Female rates over time
male_trend = male_all.groupby('year')['homicide_rate'].median()
female_trend = female_all.groupby('year')['homicide_rate'].median()
common_years = sorted(set(male_trend.index) & set(female_trend.index))

ax_l.plot(common_years, [male_trend[y] for y in common_years],
          color=COLORS['male'], linewidth=2.5, marker='o', markersize=4, label='Male')
ax_l.plot(common_years, [female_trend[y] for y in common_years],
          color=COLORS['female'], linewidth=2.5, marker='s', markersize=4, label='Female')
ax_l.set_xlabel('Year')
ax_l.set_ylabel('Median Homicide Rate (per 100,000)')
ax_l.set_title('Median Homicide Rate by Sex')
ax_l.legend()

# M/F Ratio over time
ax_r.plot(mf_ratio_global.index, mf_ratio_global.values,
          color=COLORS['primary'], linewidth=2.5, marker='D', markersize=4)
ax_r.axhline(y=mf_ratio_global.median(), color=COLORS['accent'], linestyle='--',
             alpha=0.7, label=f'Overall Median: {mf_ratio_global.median():.1f}x')
ax_r.set_xlabel('Year')
ax_r.set_ylabel('Male-to-Female Ratio')
ax_r.set_title('Male-to-Female Homicide Rate Ratio Over Time')
ax_r.legend()

fig.tight_layout()
chart3_b64 = chart_to_base64(fig)


# ─── Chart 4: Age Group Analysis ─────────────────────────────────────────────
age_groups_standard = ['0-14', '15-29', '30-44', '45-59', '60+']
age_filtered = age_data[age_data['age_group'].isin(age_groups_standard)]
age_trend = age_filtered.groupby(['year', 'age_group'])['homicide_rate'].median().unstack('age_group')

# Ensure column order
age_trend = age_trend[[c for c in age_groups_standard if c in age_trend.columns]]

fig, ax = plt.subplots(figsize=(10, 5.5))
for i, col in enumerate(age_trend.columns):
    ax.plot(age_trend.index, age_trend[col], linewidth=2.2, marker='o', markersize=3,
            color=COLORS['age_colors'][i % len(COLORS['age_colors'])], label=col)
ax.set_xlabel('Year')
ax.set_ylabel('Median Homicide Rate (per 100,000)')
ax.set_title('Homicide Rate by Age Group Over Time')
ax.legend(title='Age Group', loc='upper right')
fig.tight_layout()
chart4_b64 = chart_to_base64(fig)


# ─── Chart 5: Notable Trends & Outliers ──────────────────────────────────────
# Find countries with most dramatic changes (earliest vs latest rate)
country_first = both_all.sort_values('year').groupby('country').agg(
    first_rate=('homicide_rate', 'first'),
    first_year=('year', 'first'),
    last_rate=('homicide_rate', 'last'),
    last_year=('year', 'last'),
    n_years=('year', 'count')
).reset_index()

# Only consider countries with at least 5 years of data spanning at least 10 years
country_first['span'] = country_first['last_year'] - country_first['first_year']
reliable = country_first[(country_first['n_years'] >= 5) & (country_first['span'] >= 10)].copy()
